diff --git a/mailnews/base/src/HeaderReader.h b/mailnews/base/src/HeaderReader.h
index c8d10954412..6e52c4c6a92 100644
--- a/mailnews/base/src/HeaderReader.h
+++ b/mailnews/base/src/HeaderReader.h
@@ -184,7 +184,7 @@ class HeaderReader {
 template <typename HeaderFn>
 mozilla::Span<const char> HeaderReader::Parse(mozilla::Span<const char> data,
                                               HeaderFn hdrCallback) {
-  // If were're resuming, skip what we've already scanned.
+  // If we're resuming, skip what we've already scanned.
   auto remaining = mozilla::Span<const char>(data.cbegin() + mPos, data.cend());
   if (mFinished) {
     return remaining;
@@ -286,7 +286,7 @@ bool HeaderReader::HandleLine(mozilla::Span<const char> line,
   }
   auto val = colon + 1;
   if (*val == ' ' || *val == '\t') {
-    // Skip single leading whitespace.
+    // Skip single leading whitespace (WSP).
     ++val;
   }

diff --git a/mailnews/local/src/nsParseMailbox.cpp b/mailnews/local/src/nsParseMailbox.cpp
index e66cc60f999..c112aea439b 100644
--- a/mailnews/local/src/nsParseMailbox.cpp
+++ b/mailnews/local/src/nsParseMailbox.cpp
@@ -81,9 +81,6 @@ static nsCString RemoveAngleBrackets(nsACString const& s) {
 //
 // Does not generate missing Message-Id (nsParseMailMessageState uses an
 // md5sum of the header block).
-//
-// Does not strip surrounding '<' and '>' from Message-Id.
-//
 RawHdr ParseMsgHeaders(mozilla::Span<const char> raw) {
   // NOTE: old code aggregates multiple To: and Cc: header occurrences.
   // Turns them into comma-separated lists.
@@ -144,7 +141,9 @@ RawHdr ParseMsgHeaders(mozilla::Span<const char> raw) {
         out.references = hdr.Value(raw);
       }
     } else if (n.LowerCaseEqualsLiteral("message-id")) {
-      out.messageId = RemoveAngleBrackets(hdr.Value(raw));
+      nsAutoCString value(hdr.Value(raw));
+      value.Trim(" \t");  // Trim WSP
+      out.messageId = RemoveAngleBrackets(value);
     } else if (n.LowerCaseEqualsLiteral("newsgroups")) {
       // We _might_ need this for recipients (see below).
       newsgroups = hdr.Value(raw);
